insert into public.cards (id, owner_id, data) values
('2bfedc22-f8ae-5dda-baf5-89802d04a35c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2bfedc22-f8ae-5dda-baf5-89802d04a35c", "code": "12ER-039", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "taux de variation"], "front": "**Taux de variation** de $f$ entre $a$ et $a+h$ : formule ? Interprétation graphique ?", "back": "$\\dfrac{f(a+h) - f(a)}{h}$\nC''est le **coefficient directeur de la sécante** qui passe par les points de la courbe d''abscisses $a$ et $a+h$.", "createdAt": 1793727914889, "updatedAt": 1793727914889, "ocrDone": true}'::jsonb),
('0a4843ce-1f5c-5012-8b59-27d541b1ca0a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0a4843ce-1f5c-5012-8b59-27d541b1ca0a", "code": "12ER-040", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "nombre dérivé", "définition"], "front": "Définition du **nombre dérivé** $f''(a)$ ?", "back": "Si le taux de variation $\\dfrac{f(a+h) - f(a)}{h}$ tend vers un nombre réel quand $h$ tend vers 0, ce nombre est $f''(a)$ et $f$ est **dérivable en $a$**.\n$f''(a) = \\lim\\limits_{h \\to 0} \\dfrac{f(a+h) - f(a)}{h}$", "createdAt": 1793727914890, "updatedAt": 1793727914890, "ocrDone": true}'::jsonb),
('564b47ff-a3d8-5a70-80e7-069f50f04477', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "564b47ff-a3d8-5a70-80e7-069f50f04477", "code": "12ER-041", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "nombre dérivé", "tangente"], "front": "Que représente $f''(a)$ **sur la courbe** de $f$ ?", "back": "Le **coefficient directeur de la tangente** à la courbe au point $A(a\\,;\\,f(a))$.\nTangente horizontale : $f''(a) = 0$.", "createdAt": 1793727914891, "updatedAt": 1793727914891, "ocrDone": true}'::jsonb),
('7c3d77d4-62bd-52d7-b3ab-2e7a80e22f95', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7c3d77d4-62bd-52d7-b3ab-2e7a80e22f95", "code": "12ER-042", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "tangente", "formule"], "front": "**Équation de la tangente** à la courbe de $f$ au point d''abscisse $a$ ?", "back": "$y = f''(a)\\,(x - a) + f(a)$\nIl faut donc calculer **deux nombres** : $f(a)$ et $f''(a)$.", "createdAt": 1793727914892, "updatedAt": 1793727914892, "ocrDone": true}'::jsonb),
('25b10d4a-bfc5-53f2-841f-8492a3203d7f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "25b10d4a-bfc5-53f2-841f-8492a3203d7f", "code": "12ER-043", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "nombre dérivé", "exemple"], "front": "**Exemple** : avec la définition, calculer le nombre dérivé de $f(x) = x^2$ en $a = 3$.", "back": "$\\dfrac{f(3+h) - f(3)}{h} = \\dfrac{9 + 6h + h^2 - 9}{h} = 6 + h$\nQuand $h$ tend vers 0, on obtient $f''(3) = 6$.", "createdAt": 1793727914893, "updatedAt": 1793727914893, "ocrDone": true}'::jsonb),
('c42be42c-041a-558f-8726-903789a564d8', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c42be42c-041a-558f-8726-903789a564d8", "code": "12ER-044", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "tangente", "exemple"], "front": "**Exemple** : équation de la tangente à la courbe de $f(x) = x^2$ au point d''abscisse 1 ?", "back": "$f(1) = 1$ et $f''(x) = 2x$ donc $f''(1) = 2$.\n$y = 2(x - 1) + 1$, soit $y = 2x - 1$.", "createdAt": 1793727914894, "updatedAt": 1793727914894, "ocrDone": true}'::jsonb),
('4a8ba340-6f38-5247-bcf1-00602db99723', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4a8ba340-6f38-5247-bcf1-00602db99723", "code": "12ER-045", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "dérivées usuelles"], "front": "**Dérivées usuelles** : $k$ (constante), $x$, $x^2$, $x^3$, $x^n$ ?", "back": "<table style=\"border-collapse:collapse;margin:8px auto\"><tr><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$f(x)$</td><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$f''(x)$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$k$</td><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$0$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$x$</td><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$1$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$x^2$</td><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$2x$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$x^3$</td><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$3x^2$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$x^n$</td><td style=\"border:1px solid #999;padding:4px 10px;text-align:center\">$n\\,x^{n-1}$</td></tr></table>Valables sur $\\mathbb{R}$ ($n$ entier, $n \\geq 1$).", "createdAt": 1793727914895, "updatedAt": 1793727914895, "ocrDone": true}'::jsonb),
('cab0a032-903f-58c8-a6e5-fa26016b5c0c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "cab0a032-903f-58c8-a6e5-fa26016b5c0c", "code": "12ER-046", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "dérivées usuelles", "piège"], "front": "Dérivées de $\\dfrac{1}{x}$ et de $\\sqrt{x}$ ? Sur quels intervalles ?", "back": "$\\left(\\dfrac{1}{x}\\right)'' = -\\dfrac{1}{x^2}$, sur $]-\\infty\\,;0[$ et $]0\\,;+\\infty[$\n$\\left(\\sqrt{x}\\right)'' = \\dfrac{1}{2\\sqrt{x}}$, sur $]0\\,;+\\infty[$\n**Attention** : $\\sqrt{x}$ est définie en 0 mais **pas dérivable** en 0.", "createdAt": 1793727914896, "updatedAt": 1793727914896, "ocrDone": true}'::jsonb),
('5ec7f4e5-66c8-50d8-8f45-484e4ae48f66', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5ec7f4e5-66c8-50d8-8f45-484e4ae48f66", "code": "12ER-047", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "opérations"], "front": "Dérivée d''une **somme** $u + v$ et d''un **produit par un réel** $k\\,u$ ?", "back": "$(u + v)'' = u'' + v''$\n$(k\\,u)'' = k\\,u''$\nEx. : $(5x^3 - 2x)'' = 15x^2 - 2$", "createdAt": 1793727914897, "updatedAt": 1793727914897, "ocrDone": true}'::jsonb),
('60285b46-8aff-5e1d-beb4-e56c188f5e12', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "60285b46-8aff-5e1d-beb4-e56c188f5e12", "code": "12ER-048", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "opérations", "piège"], "front": "Dérivée d''un **produit** $u\\,v$ ?", "back": "$(u\\,v)'' = u''\\,v + u\\,v''$\n**Piège** : ce n''est pas $u''\\,v''$ !", "createdAt": 1793727914898, "updatedAt": 1793727914898, "ocrDone": true}'::jsonb),
('2905717d-2595-57cd-a01f-12a2bc1fb554', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2905717d-2595-57cd-a01f-12a2bc1fb554", "code": "12ER-049", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "opérations"], "front": "Dérivée de l''**inverse** $\\dfrac{1}{v}$ et d''un **quotient** $\\dfrac{u}{v}$ ?", "back": "$\\left(\\dfrac{1}{v}\\right)'' = -\\dfrac{v''}{v^2}$\n$\\left(\\dfrac{u}{v}\\right)'' = \\dfrac{u''\\,v - u\\,v''}{v^2}$ (là où $v$ ne s''annule pas)\nOrdre au numérateur : on commence par $u''$.", "createdAt": 1793727914899, "updatedAt": 1793727914899, "ocrDone": true}'::jsonb),
('077f5540-fa80-5064-ac96-4ff18b1ff46b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "077f5540-fa80-5064-ac96-4ff18b1ff46b", "code": "12ER-050", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "opérations", "composée"], "front": "Dérivée de $x \\mapsto g(ax + b)$ ?", "back": "$a \\times g''(ax + b)$\nEx. : $\\left((3x - 1)^2\\right)'' = 3 \\times 2(3x - 1) = 6(3x - 1)$\nEx. : $\\left(\\sqrt{2x + 4}\\right)'' = \\dfrac{2}{2\\sqrt{2x + 4}} = \\dfrac{1}{\\sqrt{2x + 4}}$", "createdAt": 1793727914900, "updatedAt": 1793727914900, "ocrDone": true}'::jsonb),
('ba03679e-9302-592e-99df-493dbd155278', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ba03679e-9302-592e-99df-493dbd155278", "code": "12ER-051", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "opérations", "exemple"], "front": "**Exemple** : dériver $f(x) = (2x + 1)(x^2 - 3)$.", "back": "$u = 2x + 1$, $u'' = 2$ ; $v = x^2 - 3$, $v'' = 2x$\n$f''(x) = 2(x^2 - 3) + (2x + 1) \\times 2x = 6x^2 + 2x - 6$", "createdAt": 1793727914901, "updatedAt": 1793727914901, "ocrDone": true}'::jsonb),
('91e2d20b-cfc5-52db-956e-0e3986881df8', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "91e2d20b-cfc5-52db-956e-0e3986881df8", "code": "12ER-052", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "opérations", "exemple"], "front": "**Exemple** : dériver $f(x) = \\dfrac{2x + 1}{x - 3}$ sur $]3\\,;+\\infty[$.", "back": "$u = 2x + 1$, $u'' = 2$ ; $v = x - 3$, $v'' = 1$\n$f''(x) = \\dfrac{2(x - 3) - (2x + 1)}{(x - 3)^2} = \\dfrac{-7}{(x - 3)^2}$", "createdAt": 1793727914902, "updatedAt": 1793727914902, "ocrDone": true}'::jsonb),
('da546211-b17c-5f6d-97b9-3aef129d9dbb', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "da546211-b17c-5f6d-97b9-3aef129d9dbb", "code": "12ER-053", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "variations"], "front": "Lien entre le **signe de $f''$** et les **variations** de $f$ sur un intervalle ?", "back": "$f'' \\geq 0$ sur $I$ : $f$ **croissante** sur $I$\n$f'' \\leq 0$ sur $I$ : $f$ **décroissante** sur $I$\n$f'' = 0$ sur $I$ : $f$ **constante** sur $I$", "createdAt": 1793727914903, "updatedAt": 1793727914903, "ocrDone": true}'::jsonb),
('b750e5e0-3170-5e00-9c10-74213811ce80', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b750e5e0-3170-5e00-9c10-74213811ce80", "code": "12ER-054", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "variations", "méthode"], "front": "Méthode : étudier les **variations** d''une fonction $f$ ?", "back": "1. Calculer $f''(x)$.\n2. **Factoriser** $f''(x)$ (ou reconnaître un trinôme) pour étudier son signe.\n3. Tableau de signes de $f''$, puis tableau de variations de $f$.\n4. Calculer les valeurs de $f$ aux bornes et aux extremums.", "createdAt": 1793727914904, "updatedAt": 1793727914904, "ocrDone": true}'::jsonb),
('80042edf-0f29-5140-86d9-7ce027f1557b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "80042edf-0f29-5140-86d9-7ce027f1557b", "code": "12ER-055", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "cours", "dérivation", "extremum", "piège"], "front": "Quand $f$ admet-elle un **extremum local** en $a$ ?", "back": "Quand $f''$ **s''annule en changeant de signe** en $a$.\n**Piège** : $f''(a) = 0$ ne suffit pas. Ex. : $f(x) = x^3$, $f''(0) = 0$ mais $f$ est croissante sur $\\mathbb{R}$ (pas d''extremum).", "createdAt": 1793727914905, "updatedAt": 1793727914905, "ocrDone": true}'::jsonb);
