begin;
update public.groups set data = jsonb_set(data, '{tracks}', data->'tracks' || '[{"subject": "Mathématiques", "level": "1re"}]'::jsonb) where id = '3c6873cc-cb98-4b74-a154-54b8730cdeb8' and not (data->'tracks' @> '[{"subject": "Mathématiques", "level": "1re"}]'::jsonb);
commit;
select (select count(*) from public.units where data->>'subject'='Mathématiques' and data->>'level'='1re') as points, (select count(*) from public.unit_cards uc join public.units u on u.id=uc.unit_id where u.data->>'subject'='Mathématiques' and u.data->>'level'='1re') as liens, (select data->'tracks' from public.groups where id='3c6873cc-cb98-4b74-a154-54b8730cdeb8') as parcours, (select jsonb_array_length(data->'cardIds') from public.tutoring_sessions where id='812504c6-0643-5122-996d-c6777dd587d4') as flashcards_seance;
